 "content": "from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    # Find color markers arranged as four corners of lattice cells.
    rare = {c for c, n in counts.items() if n <= max(12, h * w // 20)}
    blocks = []
    for color in rare:
        pts = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == color}
        rows = sorted({r for r, _ in pts})
        cols = sorted({c for _, c in pts})
        rects = []
        for i, r1 in enumerate(rows):
            for r2 in rows[i + 1:]:
                for j, c1 in enumerate(cols):
                    for c2 in cols[j + 1:]:
                        if {(r1,c1),(r1,c2),(r2,c1),(r2,c2)} <= pts:
                            rects.append((r1,r2,c1,c2))
        if rects:
            dy = min(r2-r1 for r1,r2,c1,c2 in rects)
            dx = min(c2-c1 for r1,r2,c1,c2 in rects)
            for r1,r2,c1,c2 in rects:
                if r2-r1 == dy and c2-c1 == dx:
                    blocks.append((r1,r2,c1,c2,color,dy,dx))
    if not blocks:
        return [[min(counts, key=counts.get)]]

    # Extent is the bounding rectangle of all marked lattice vertices.
    r0 = min(b[0] for b in blocks); r1 = max(b[1] for b in blocks)
    c0 = min(b[2] for b in blocks); c1 = max(b[3] for b in blocks)
    dy = Counter(b[5] for b in blocks).most_common(1)[0][0]
    dx = Counter(b[6] for b in blocks).most_common(1)[0][0]
    nr = (r1-r0)//dy
    nc = (c1-c0)//dx
    # Background is the dominant room/interior color (not a rare marker).
    bg = max((c for c in counts if c not in rare), key=lambda c: counts[c])
    out = [[bg for _ in range(nc)] for _ in range(nr)]
    for top, bottom, left, right, color, _, _ in blocks:
        rr = (top-r0)//dy
        cc = (left-c0)//dx
        if 0 <= rr < nr and 0 <= cc < nc:
            out[rr][cc] = color
    return out
